recipes.code:
{
  "inputs": [
    {
      "id": "banksync-api-key",
      "type": "promptString",
      "description": "Your BankSync API key from https://banksync.io/developers",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@banksync/mcp@1.0.2"
      ],
      "env": {
        "BANKSYNC_API_KEY": "${input:banksync-api-key}"
      }
    }
  }
}
